class Shape:
    def area(self):
        raise NotImplementedError("자식 클래스에서 만들어야 해요")


class Square(Shape):
    def __init__(self, side):
        self.side = side

    def area(self):
        return self.side * self.side

setup:
def run_ops(obj, steps):
    out = []
    for step in steps:
        name, *args = step
        if name == "attr":
            out.append(getattr(obj, args[0]))
        elif name == "set":
            setattr(obj, args[0], args[1])
        else:
            r = getattr(obj, name)(*args)
            if r is not None:
                out.append(r)
    return out


def raises(fn):
    try:
        fn()
    except Exception as e:
        return type(e).__name__
    return None
